class PackageView(types.ModuleType):
    def __getattr__(self, name):
        if name in OWNERS:
            return getattr(self._modules[OWNERS[name]], name)
        # Standard-library patch targets belong to this test adapter.
        if name in ("subprocess", "shutil", "sys"):
            return globals()[name]
        return getattr(self._modules['state'], name)

    def __setattr__(self, name, value):
        if name in OWNERS:
            setattr(self._modules[OWNERS[name]], name, value)
        else:
            super().__setattr__(name, value)

    def __delattr__(self, name):
        if name in OWNERS:
            delattr(self._modules[OWNERS[name]], name)
        else:
            super().__delattr__(name)

class MonitorLoader(importlib.machinery.SourceFileLoader):
    def exec_module(self, module):
        if Path(self.path).name != 'nrp-monitor':
            return super().exec_module(module)
        package = Path(self.path).resolve().parent / 'nrp_monitor'
        # Unique package identity also isolates deferred relative imports.
        alias = '_nrp_monitor_' + self.name + '_' + uuid.uuid4().hex
        spec = importlib.util.spec_from_file_location(alias, package / '__init__.py', submodule_search_locations=[str(package)])
        instance = importlib.util.module_from_spec(spec)
        sys.modules[alias] = instance
        spec.loader.exec_module(instance)
        modules = {name: importlib.import_module(alias + '.' + name) for name in sorted(set(OWNERS.values()))}
        module.__class__ = PackageView
        module._modules = modules

machinery = types.SimpleNamespace(SourceFileLoader=MonitorLoader)
